initial_condition:
with {
    the SUT being in the "initial state" and
    and containing a list of entities
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Batch Upsert Entities with Response Status Code set to 204     and
        Query Entities with Updated Entities set to '${entities_to_be_upserted}' valid entities
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/entityOperations/upsert?options=${update_option}'
        method set to 'POST'
        Request batch upsert operation over entity from filename '@{entities_to_be_upserted}' with update_option set to 'replace' and Content-Type set to 'application/ld+json'
}

